import { test, expect } from '@playwright/test';

test.describe('User Registration - Email Already Exists Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/register');
  });

  test('should display error when registering with an already used email', async ({ page }) => {
    // Setup: Register with a valid email first
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    const registerButton = page.getByRole('button', { name: /register/i });

    await emailInput.fill('testuser@example.com');
    await passwordInput.fill('ValidPassword123');
    await confirmPasswordInput.fill('ValidPassword123');
    await registerButton.click();

    // Verify successful registration
    await expect(page.getByText('Registration successful')).toBeVisible();
    await expect(page).toHaveURL(/.*dashboard/);

    // Navigate back to registration page
    await page.goto('/register');

    // Attempt to register with the same email again
    await emailInput.fill('testuser@example.com');
    await passwordInput.fill('AnotherPassword123');
    await confirmPasswordInput.fill('AnotherPassword123');
    await registerButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('This email is already registered');
    await expect(errorMessage).toBeVisible();

    // Verify error message is styled correctly (e.g, red text)
    const errorContainer = page.locator('[data-testid="error-message"]');
    await expect(errorContainer).toHaveCSS('color', 'rgb(252, 10, 36)');

    // Verify user remains on the registration page
    await expect(page).toHaveURL(/.*register/);
  });

  test('should clear error message when user corrects email and resubmits', async ({ page }) => {
    // Setup: Register with a valid email first
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    const registerButton = page.getByRole('button', { name: /register/i });

    await emailInput.fill('testuser@example.com');
    await passwordInput.fill('ValidPassword123');
    await confirmPasswordInput.fill('ValidPassword123');
    await registerButton.click();

    // Verify successful registration
    await expect(page.getByText('Registration successful')).toBeVisible();
    await expect(page).toHaveURL(/.*dashboard/);

    // Navigate back to registration page
    await page.goto('/register');

    // Attempt to register with the same email (trigger error)
    await emailInput.fill('testuser@example.com');
    await passwordInput.fill('AnotherPassword123');
    await confirmPasswordInput.fill('AnotherPassword123');
    await registerButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('This email is already registered');
    await expect(errorMessage).toBeVisible();

    // Correct the email and resubmit
    await emailInput.fill('newuser@example.com');
    await passwordInput.fill('NewPassword123');
    await confirmPasswordInput.fill('NewPassword123');
    await registerButton.click();

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText('Registration successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    await expect(page).toHaveURL(/.*dashboard/);
  });
});
